                    'cash_agent' => $this->input->post('cash_agent'),
                    'mobile' => $this->input->post('mobile'),
                    'is_active' => $this->input->post('is_active'),
                    'is_locked' => $this->input->post('is_locked'),
                    'updated_by' => $this->session->userdata['id'],
                    //'updated_date' => $this->input->post('updated_date'),
                    'address' => $this->input->post('address'),
                );

                $tbl_admin_id = $this->Tbl_admin_model->add_tbl_admin($params);
                //echo $tbl_admin_id; die;
                redirect('/admin_master');
            }
        }
        //else
        // {            
        $data['tbl_admin'] = $this->Tbl_admin_model->get_all_tbl_admin();
        $data['_view'] = 'tbl_admin/add';
        $this->load->view('layouts/main', $data);
