    /*
     * Deleting tbl_admin
     */
    function remove($id)
    {
        $tbl_admin = $this->Tbl_admin_model->get_tbl_admin($id);

        // check if the tbl_admin exists before trying to delete it
        if (isset($tbl_admin['id'])) {
            $this->Tbl_admin_model->delete_tbl_admin($id);
